                }`}
                aria-invalid={error ? "true" : "false"}
                aria-describedby={error ? `${id}-error` : (helperText ? `${id}-helper` : undefined)}
                required={required}
            />
            {helperText && !error && (
                <p id={`${id}-helper`} className="helper-text">
                    {helperText}
                </p>
            )}
            {error && (
                <p id={`${id}-error`} className="error-message">
                    {error}
                </p>
            )}
        </div>
    );
};

const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });
    const [errors, setErrors] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const validate = (name, value) => {
        let error = '';
        if (name === 'fullName' && !value.trim()) {
            error = 'Full name is required';
        } else if (name === 'email') {
            if (!value.trim()) {
                error = 'Email address is required';
            } else if (!/\S+@\S+\.\S+/.test(value)) {
                error = 'Please enter a valid email address';
            }
        } else if (name === 'phone' && value.trim()) {
            // Optional but format check if provided
            const phoneRegex = /^\+?[\d\s-]{10,}$/;
            if (!phoneRegex.test(value)) {
                error = 'Invalid phone format (min 10 digits)';
            }
        }
        return error;
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));

        // Clear error when user types
        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const newErrors = {};
        Object.keys(formData).forEach(key => {
            const error = validate(key, formData[key]);
            if (error) newErrors[key] = error;
        });

        if (Object.keys(newErrors).length === 0) {
            console.log('Form Submitted:', formData);
            setSubmitted(true);
            // In a real app, you'd send this to a server
        } else {
            setErrors(newErrors);
        }
    };

    if (submitted) {
        return (
            <div className="bg-white p-8 rounded-2xl shadow-xl text-center">
                <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                </div>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">Message Sent!</h2>
                <p className="text-gray-600 mb-6">Thank you for reaching out. Our support team will get back to you soon.</p>
                <button 
                    onClick={() => {setSubmitted(false); setFormData({fullName: '', email: '', phone: ''});}}
                    className="text-blue-600 font-medium hover:underline"
                >
                    Send another message
                </button>
            </div>
        );
    }

    return (
        <div className="bg-white p-8 rounded-2xl shadow-xl">
            <div className="mb-8">
                <h1 className="text-2xl font-bold text-gray-800">Contact Support</h1>
                <p className="text-gray-600">We're here to help. Fill out the form below.</p>
            </div>
            <form onSubmit={handleSubmit} noValidate>
                <FormField
                    label="Full Name"
                    id="fullName"
                    value={formData.fullName}
                    onChange={handleChange}
                    error={errors.fullName}
                    required
                    placeholder="Jane Doe"
                />
                <FormField
                    label="Email Address"
                    id="email"
                    type="email"
                    value={formData.email}
                    onChange={handleChange}
                    error={errors.email}
                    required
                    placeholder="jane@example.com"
                />
                <FormField
                    label="Phone Number"
                    id="phone"
                    type="tel"
                    value={formData.phone}
                    onChange={handleChange}
                    error={errors.phone}
                    helperText="Expected format: +1 123 456 7890 (min 10 digits)"
                    placeholder="+1 123 456 7890"
                />
                <button
                    type="submit"
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-4 rounded-lg transition-colors duration-200 shadow-lg hover:shadow-xl mt-4"
                >
                    Submit Request
                </button>
            </form>
        </div>
    );
};

const App = () => {
    return (
        <div className="py-12">
            <ContactForm />
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
